package main

import _ "embed"

// Generated by task extract-ng-collation from the competition's MySQL.
// Each valid BMP scalar has one two-byte weight; supplementary scalars share
// the final weight. LIKE compares characters, without equality's space padding.
//
//go:embed ng_general_ci.bin
var ngGeneralCI string

const (
	ngStar = uint32(65536)
	ngAny  = uint32(65537)
)

type ngPattern struct{ tokens []uint32 }

func ngWeight(r rune) uint32 {
	if r > 65535 {
		r = 65536
	}
	i := int(r) * 2
	return uint32(ngGeneralCI[i])<<8 | uint32(ngGeneralCI[i+1])
}

func compileNG(word string) *ngPattern {
	// Compile the entire SQL pattern: a final backslash in the word escapes
	// the appended percent sign, so it must not be treated as a substring.
	runes := []rune("%" + word + "%")
	p := &ngPattern{tokens: make([]uint32, 0, len(runes))}
	for i := 0; i < len(runes); i++ {
		r := runes[i]
		var token uint32
		switch r {
		case '\\':
			if i+1 < len(runes) {
				i++
				r = runes[i]
			}
			token = ngWeight(r)
		case '%':
			token = ngStar
		case '_':
			token = ngAny
		default:
			token = ngWeight(r)
		}
		if token == ngStar && len(p.tokens) > 0 && p.tokens[len(p.tokens)-1] == ngStar {
			continue
		}
		p.tokens = append(p.tokens, token)
	}
	return p
}

func (p *ngPattern) matches(text []uint32) bool {
	// Greedy LIKE matching, remembering the latest percent for backtracking.
	i, j, star, retry := 0, 0, -1, 0
	for i < len(text) {
		if j < len(p.tokens) && p.tokens[j] != ngStar && (p.tokens[j] == ngAny || p.tokens[j] == text[i]) {
			i++
			j++
		} else if j < len(p.tokens) && p.tokens[j] == ngStar {
			star, retry = j, i
			j++
		} else if star >= 0 {
			retry++
			i, j = retry, star+1
		} else {
			return false
		}
	}
	for j < len(p.tokens) && p.tokens[j] == ngStar {
		j++
	}
	return j == len(p.tokens)
}

func matchesNG(text string, patterns []*ngPattern) bool {
	if len(patterns) == 0 {
		return false
	}
	var scratch [255]uint32
	weights := scratch[:0]
	for _, r := range text {
		weights = append(weights, ngWeight(r))
	}
	for _, pattern := range patterns {
		if pattern.matches(weights) {
			return true
		}
	}
	return false
}
